//! 🌐️ Two actual admitted Composite views retain independent metadata through stationary fanout and cancellation.
use super::*;
use crate::original_view::routing::OriginalHostEventRoutes;
fn quantum()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,..stock()}}
fn run<T>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,action:impl FnOnce(&mut StepContext<'_>)->Result<T,OriginalTurnFailure>)->T{caller.turn_with_decoder(quantum(),decoder,action).unwrap()}
fn metadata(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,rows:&[serde_json::Value],target:&str)->ActionMeta{
 let mut view=ViewModel::new(semio_ui_locale::Locale::En,semio_ui_locale::Terminology::Native);view.window_id=Some(target.into());view.active_window_kind_id=Some("raster.composite".into());for row in rows{view.window_instances.push(semio_framework::ViewWindowInstance{id:row["id"].as_str().unwrap().into(),window_kind_id:row["kind"].as_str().unwrap().into()});}let mut original=Some(view);let mut root=None;let mut frame=semio_framework_value::native_decoding::NativeSharedAdmission::default();for _ in 0..1024{if run(caller,decoder,|cx|ActionMeta::admit_view_root(&mut original,&mut root,&mut frame,cx)){break}}let mut actor=None;run(caller,decoder,|cx|{let turn=semio_framework_os_kernel::ActorId::admit_seed("host-events:fixture",cx.retained_grant());let result=turn.result.map(|value|{let(value,p)=value.expect("funded fixture actor seed");actor=Some(value.0);semio_framework_value::RetainedCloneStep::Progress(p)});semio_framework_job::receive_original_retained_work(cx,RetainedWorkOutcome{result,work:turn.work})?;Ok(())});ActionMeta{actor:actor.unwrap(),instance_id:71,view_state:root,expected_document_revision:Some([19;32])}
}
fn retire<T:semio_framework_value::RetireOwned>(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,value:T){let mut owner=ControlledRetirement::retain(value);for _ in 0..65536{if owner.terminal_is_empty(){break}run(caller,decoder,|cx|cx.with_original_retirement(|cx|{let d=owner.selected_demand(32768)?;semio_framework_job::close_original_retained_step(cx,d,|g|{let result=owner.step(g);RetainedWorkOutcome{result,work:owner.last_turn_work()}})?;Ok(())}));}assert!(owner.terminal_is_empty());}
#[test]
fn stationary_peer_fanout_uses_live_original_window_aliases(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../fixture.json")).unwrap();for case in law["cases"].as_array().unwrap(){let mut caller=OriginalJobFixtureCaller::admit(OperationId(702),Generation(14),stock(),||Some(1),u64::MAX,1<<20);let mut decoder=OriginalJobDecodeOwner::empty();let mut routes=OriginalHostEventRoutes::default();let rows=law["windows"].as_array().unwrap();if case["view"]==true{for row in rows{let meta=metadata(&mut caller,&mut decoder,rows,row["id"].as_str().unwrap());for _ in 0..65536{if run(&mut caller,&mut decoder,|cx|routes.capture(&meta,cx)){break}}assert_eq!(routes.route(routes.extent()-1).unwrap().actor.as_str(),"host-events:fixture");assert!(routes.route(routes.extent()-1).unwrap().expected_document_revision.is_none());retire(&mut caller,&mut decoder,meta);}if case["retired"].is_array(){let live=rows.iter().filter(|row|!case["retired"].as_array().unwrap().iter().any(|id|id==&row["id"])).cloned().collect::<Vec<_>>();let meta=metadata(&mut caller,&mut decoder,&live,live[0]["id"].as_str().unwrap());for _ in 0..65536{if run(&mut caller,&mut decoder,|cx|routes.capture(&meta,cx)){break}}retire(&mut caller,&mut decoder,meta);}}
 routes.base_moved();let mut actual=Vec::<String>::new();if case["activeAction"]==true{assert!(!routes.runnable(true));}else if case["cancelled"]==true{run(&mut caller,&mut decoder,|cx|routes.start(cx));for _ in 0..1024{if run(&mut caller,&mut decoder,|cx|routes.advance_liveness(cx)).is_some(){break}}run(&mut caller,&mut decoder,|cx|routes.prepare_metadata(cx));run(&mut caller,&mut decoder,|cx|routes.prepare_event(cx));caller.cancel().cancel_now();while !routes.delivery_is_empty(){run(&mut caller,&mut decoder,|cx|routes.close_delivery(cx));}run(&mut caller,&mut decoder,|cx|routes.finish_cancelled(cx));assert!(!routes.pending());}else{for _ in 0..65536{if !routes.pending(){break}run(&mut caller,&mut decoder,|cx|{if !routes.start(cx)?{return Ok(())}if routes.cursor==routes.extent(){routes.finish(cx)?;return Ok(())}match routes.advance_liveness(cx)?{None=>return Ok(()),Some(false)=>{routes.next_window(cx)?;return Ok(())},Some(true)=>{}}if !routes.prepare_metadata(cx)?{return Ok(())}if !routes.prepare_event(cx)?{return Ok(())}Ok(())});if let Some(event)=routes.event.as_ref(){actual.push(event.window_id().into());while !routes.delivery_is_empty(){run(&mut caller,&mut decoder,|cx|routes.close_delivery(cx));}run(&mut caller,&mut decoder,|cx|routes.next_window(cx));}}assert!(!routes.pending());}let expected:Vec<String>=serde_json::from_value(case["expected"].clone()).unwrap();assert_eq!(actual,expected,"{}",case["name"]);for _ in 0..65536{if routes.terminal_is_empty(){break}run(&mut caller,&mut decoder,|cx|cx.with_original_retirement(|cx|routes.close_step(cx)));}assert!(routes.terminal_is_empty());while !decoder.terminal_is_empty(){caller.turn(quantum(),|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(32768)?;semio_framework_job::close_original_retained_step(cx,d,|g|decoder.close_step(g))?;Ok(())})).unwrap();}caller.retire(stock());}
}
